-- Chacha Prime Master SQL Schema
-- Manual MySQL import. No Laravel migrations.
CREATE DATABASE IF NOT EXISTS `u293300332_chacha` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `u293300332_chacha`;
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NULL,phone VARCHAR(40) NULL,country VARCHAR(100) NULL,email_verified_at TIMESTAMP NULL, two_factor_secret TEXT NULL,two_factor_enabled TINYINT(1) NOT NULL DEFAULT 0,status ENUM('active','blocked','pending') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS customer_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,address TEXT NULL,city VARCHAR(100) NULL,state VARCHAR(100) NULL,postal_code VARCHAR(30) NULL,country VARCHAR(100) NULL,avatar VARCHAR(500) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wallets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,currency VARCHAR(10) NOT NULL DEFAULT 'USD',balance DECIMAL(18,2) NOT NULL DEFAULT 0,status ENUM('active','locked') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wallet_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,wallet_id BIGINT UNSIGNED NOT NULL,entry_type ENUM('credit','debit') NOT NULL,reason VARCHAR(80) NOT NULL,amount DECIMAL(18,2) NOT NULL,balance_after DECIMAL(18,2) NOT NULL,reference_type VARCHAR(80) NULL,reference_id BIGINT UNSIGNED NULL,description VARCHAR(500) NULL,created_at TIMESTAMP NULL,FOREIGN KEY(wallet_id) REFERENCES wallets(id) ON DELETE CASCADE,INDEX(wallet_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS brands (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL UNIQUE,slug VARCHAR(220) NOT NULL UNIQUE,logo VARCHAR(500) NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,description TEXT NULL,image VARCHAR(500) NULL,menu_order INT NOT NULL DEFAULT 0,ai_generated TINYINT(1) NOT NULL DEFAULT 0,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NULL,brand_id BIGINT UNSIGNED NULL,name VARCHAR(255) NOT NULL,title VARCHAR(255) NOT NULL,slug VARCHAR(300) NOT NULL UNIQUE,sku VARCHAR(120) NOT NULL UNIQUE,qr_payload TEXT NULL,short_description TEXT NULL,description LONGTEXT NULL,highlights LONGTEXT NULL,specifications LONGTEXT NULL,retail_price DECIMAL(18,2) NOT NULL DEFAULT 0,wholesale_price DECIMAL(18,2) NULL,group_buying_price DECIMAL(18,2) NULL,stock_qty INT NOT NULL DEFAULT 0,low_stock_threshold INT NOT NULL DEFAULT 5,brand_name VARCHAR(190) NULL,fulfillment ENUM('seller','marketplace') NOT NULL DEFAULT 'seller',return_window_business_days INT NOT NULL DEFAULT 7,status ENUM('draft','active','inactive','out_of_stock') NOT NULL DEFAULT 'draft',seo_title VARCHAR(255) NULL,seo_description TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,FOREIGN KEY(brand_id) REFERENCES brands(id) ON DELETE SET NULL,INDEX(status),INDEX(category_id),INDEX(brand_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,media_type ENUM('image','video') NOT NULL,path VARCHAR(1000) NOT NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_variations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,sku VARCHAR(120) NULL UNIQUE,attributes_json JSON NULL,retail_price DECIMAL(18,2) NULL,wholesale_price DECIMAL(18,2) NULL,group_buying_price DECIMAL(18,2) NULL,stock_qty INT NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shipping_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,economy_days INT NOT NULL DEFAULT 7,economy_price DECIMAL(18,2) NOT NULL DEFAULT 0,express_days INT NULL,express_price DECIMAL(18,2) NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_shipping (product_id BIGINT UNSIGNED PRIMARY KEY,shipping_template_id BIGINT UNSIGNED NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(shipping_template_id) REFERENCES shipping_templates(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_imports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,source_name VARCHAR(100) NOT NULL,source_url TEXT NULL,raw_data_json LONGTEXT NULL,status ENUM('imported','review','approved','failed') NOT NULL DEFAULT 'imported',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_import_media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,media_type ENUM('image','video') NOT NULL,source_url TEXT NOT NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS group_buying_campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,price DECIMAL(18,2) NOT NULL,required_buyers INT NOT NULL,current_buyers INT NOT NULL DEFAULT 0,starts_at TIMESTAMP NULL,expires_at TIMESTAMP NULL,status ENUM('draft','active','successful','failed','refunded','cancelled') NOT NULL DEFAULT 'draft',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS group_buying_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL DEFAULT 1,amount DECIMAL(18,2) NOT NULL,status ENUM('paid','pending','refunded','cancelled') NOT NULL DEFAULT 'paid',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY uq_group_buyer(campaign_id,user_id),FOREIGN KEY(campaign_id) REFERENCES group_buying_campaigns(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,INDEX(campaign_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_number VARCHAR(80) NOT NULL UNIQUE,status VARCHAR(40) NOT NULL DEFAULT 'pending',subtotal DECIMAL(18,2) NOT NULL DEFAULT 0,shipping_amount DECIMAL(18,2) NOT NULL DEFAULT 0,discount_amount DECIMAL(18,2) NOT NULL DEFAULT 0,total_amount DECIMAL(18,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'USD',payment_method VARCHAR(80) NULL,payment_status VARCHAR(40) NOT NULL DEFAULT 'pending',courier VARCHAR(100) NULL,tracking_number VARCHAR(190) NULL,delivered_at TIMESTAMP NULL,shipping_address TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,INDEX(user_id,status),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,variation_id BIGINT UNSIGNED NULL,sku VARCHAR(120) NOT NULL,title VARCHAR(255) NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(18,2) NOT NULL,total_price DECIMAL(18,2) NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT,FOREIGN KEY(variation_id) REFERENCES product_variations(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_tracking_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,status VARCHAR(40) NOT NULL,courier VARCHAR(100) NULL,tracking_number VARCHAR(190) NULL,note TEXT NULL,created_at TIMESTAMP NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,INDEX(order_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS returns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,order_item_id BIGINT UNSIGNED NOT NULL,type ENUM('refund','replacement') NOT NULL,reason TEXT NOT NULL,status ENUM('requested','approved','rejected','in_transit','received','completed','cancelled') NOT NULL DEFAULT 'requested',media_json LONGTEXT NULL,shipping_label_path VARCHAR(1000) NULL,admin_note TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NOT NULL,provider VARCHAR(80) NOT NULL,transaction_reference VARCHAR(190) NULL,amount DECIMAL(18,2) NOT NULL,currency VARCHAR(10) NOT NULL DEFAULT 'USD',status ENUM('pending','authorized','paid','failed','refunded','cancelled') NOT NULL DEFAULT 'pending',provider_payload LONGTEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,rating TINYINT NOT NULL,title VARCHAR(255) NULL,body TEXT NULL,media_json LONGTEXT NULL,status ENUM('pending','published','rejected') NOT NULL DEFAULT 'pending',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS business_verifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,business_name VARCHAR(255) NULL,business_email VARCHAR(190) NULL,country VARCHAR(100) NULL,business_address TEXT NULL,identity_type ENUM('passport','national_id','driving_license') NULL,identity_document_path VARCHAR(1000) NULL,status ENUM('pending','verified','rejected') NOT NULL DEFAULT 'pending',reviewed_by BIGINT UNSIGNED NULL,reviewed_at TIMESTAMP NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,type ENUM('fixed','percent') NOT NULL,value DECIMAL(18,2) NOT NULL,min_order_amount DECIMAL(18,2) NOT NULL DEFAULT 0,max_uses INT NULL,used_count INT NOT NULL DEFAULT 0,starts_at TIMESTAMP NULL,expires_at TIMESTAMP NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chacha_conversations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,status ENUM('open','handoff','closed') NOT NULL DEFAULT 'open',assigned_agent_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chacha_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT UNSIGNED NOT NULL,sender ENUM('customer','chacha','agent') NOT NULL,message LONGTEXT NOT NULL,metadata_json LONGTEXT NULL,created_at TIMESTAMP NULL,FOREIGN KEY(conversation_id) REFERENCES chacha_conversations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_user_id BIGINT UNSIGNED NOT NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100) NULL,entity_id BIGINT UNSIGNED NULL,details_json LONGTEXT NULL,ip_address VARCHAR(45) NULL,created_at TIMESTAMP NULL,FOREIGN KEY(admin_user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS site_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(190) NOT NULL UNIQUE,setting_value LONGTEXT NULL,is_secret TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
